import type { Card, Color } from "../../../src/domain/index.js";
import { createTestCard } from "../../utils/cardFactory.js";

interface StapleOptions {
  readonly name: string;
  readonly manaValue?: number;
  readonly typeLine: string;
  readonly oracleText: string;
  readonly colorIdentity?: readonly Color[];
  readonly canBeCommander?: boolean;
  readonly basePowerRating?: number;
}

function staple(options: StapleOptions): Card {
  return createTestCard({
    name: options.name,
    manaValue: options.manaValue ?? 0,
    typeLine: options.typeLine,
    oracleText: options.oracleText,
    colorIdentity: options.colorIdentity ?? [],
    ...(options.canBeCommander ? { canBeCommander: true } : {}),
    ...(options.basePowerRating !== undefined ? { basePowerRating: options.basePowerRating } : {}),
  });
}

function basic(name: string, color: Color, symbol: string): Card {
  return staple({
    name,
    typeLine: `Basic Land — ${name}`,
    oracleText: `({T}: Add {${symbol}}.)`,
    colorIdentity: [color],
    basePowerRating: 3,
  });
}

function dual(name: string, colors: readonly Color[], symbols: string): Card {
  return staple({
    name,
    typeLine: "Land",
    oracleText: `{T}: Add ${symbols}.`,
    colorIdentity: colors,
    basePowerRating: 6,
  });
}

function colorlessLand(name: string, oracleText: string, rating = 5): Card {
  return staple({
    name,
    typeLine: "Land",
    oracleText,
    basePowerRating: rating,
  });
}

function dino(name: string, manaValue: number, colors: readonly Color[], legendary = false, rating = 4): Card {
  return staple({
    name,
    manaValue,
    typeLine: legendary ? "Legendary Creature — Dinosaur" : "Creature — Dinosaur",
    oracleText: "Trample. Other Dinosaurs you control get +1/+1.",
    colorIdentity: colors,
    canBeCommander: legendary,
    basePowerRating: rating,
  });
}

